  /更新不易.+?看最新章节！/g,
  /更新不易.+?看最新无错章节！/g, 
  /更新不易.+?最新小说章节！/g,
  /速.?读.?谷/g, 
  /本章节未完.+?请订阅/g,
  '当&前@章#节$内%容^不&完*整！要~查!看-完_整|章;节)请(退&出%阅#读|模*式！',

]

for(let reg of FILTER_RULES){
	 result = result.replace(reg, "")
}
result;

rules.jsLib:
function towan(e) {
    if(!e) return;
    if (e < 1e4) {
        return e + "字";
    } else {
        return (e / 1e4).toFixed(1) + "万字";
    }
}

