var href = result;
var bookId1 = href.match(/(\d+)\/(\d+)/);
var bookId = (bookId1 && bookId1[2])?bookId1[2]:'0';
var prefix;
if (bookId.length <= 3) {
	prefix = '0';
} else {
	prefix = bookId.slice(0, bookId.length - 3);
}
'https://image.biqige.info/' + prefix + '/' + bookId + '/' + bookId + 's.jpg';

ruleToc.chapterList:
class.BCsectionTwo-top-chapter@li
<js>
list = result.toArray();
s = /originalOrder = .*?;/.test(src)?eval(src.match(/originalOrder = (.*?);/)[1]):result;
l = [];
if(/<li.*?"\d+" .*?-[^"]+="\d+">/.test(result)){
	num = String(result).match(/<li.*?"\d+" (.*?-[^"]+)="\d+">/)[1];
	l = list.sort((a,b)=>a.attr(num)-b.attr(num));
	}else{
for(i in list){ l[s[i]] = list[i]};
}
l.join("")
</js>
